import * as THREE from 'three';

export class GameLoop {
    constructor(game) {
        this.game = game;
        this.clock = new THREE.Clock();
        this.isRunning = false;
        // FPS tracking for tests
        this.fpsSamples = [];
        this._fpsFrameCount = 0;
        this._fpsAccumulator = 0;
        // Fixed timestep for deterministic game logic (60 Hz)
        this._fixedDt = 1 / 60;
        this._accumulator = 0;
        this._boundAnimate = () => this.animate();
        this._frameHandle = 0;
    }

    start() {
        if (this.isRunning) return;
        this.isRunning = true;
        this.clock.start();
        this.resetDelta();
        this.game.renderer?.setAnimationLoop?.(null);
        this._frameHandle = requestAnimationFrame(this._boundAnimate);
    }

    stop() {
        this.isRunning = false;
        if (this._frameHandle) cancelAnimationFrame(this._frameHandle);
        this._frameHandle = 0;
    }

    resetDelta() {
        if (!this.clock.running) {
            this.clock.start();
        }
        this.clock.getDelta();
        this._accumulator = 0;
    }

    animate() {
        if (!this.isRunning) return;

        // Do not advance simulation when the tab/app is hidden.
        // In headless mode, document.hidden is always true, so check for it.
        const isHeadless = typeof navigator !== 'undefined' && navigator.userAgent?.includes('Headless');
        if (typeof document !== 'undefined' && document.hidden && !window.__kilo_test__ && !isHeadless) {
            this.resetDelta();
            this._frameHandle = requestAnimationFrame(this._boundAnimate);
            return;
        }

        // Skip simulation when paused (e.g., kill reward screen, pause menu)
        if (this.game.isPaused) {
            // Still render to show the paused state
            if (this.game.render) this.game.render();
            this._frameHandle = requestAnimationFrame(this._boundAnimate);
            return;
        }

        const delta = this.clock.getDelta();
        const safeDelta = Math.min(0.05, Math.max(0.001, Number.isFinite(delta) ? delta : this._fixedDt));
        if (this.game.update) this.game.update(safeDelta);
        this._fpsFrameCount++;
        this._fpsAccumulator += Number.isFinite(delta) ? delta : safeDelta;
        if (this._fpsAccumulator >= 0.5) {
            const fps = Math.round(this._fpsFrameCount / this._fpsAccumulator);
            this.fpsSamples.push(fps);
            this.game.hud?.updateFpsDisplay?.(fps);
            this._fpsFrameCount = 0;
            this._fpsAccumulator = 0;
        }

        if (this.game.render) this.game.render();

        this._frameHandle = requestAnimationFrame(this._boundAnimate);
    }
}

import * as THREE from "../node_modules/three/build/three.module.js";

export class Zone {
    constructor(scene, mapSize) {
        this.scene = scene;
        this.mapSize = mapSize;
        this.currentRadius = mapSize / 2 - 0.6;
        this.targetRadius = this.currentRadius;
        this.shrinkSpeed = 0;
        this.damagePerSecond = 22;
        this.zoneMesh = null;
        this.ringMesh = null;
        this.createZone();
    }

    syncVisuals() {
        if (this.zoneMesh) {
            const walls = this.zoneMesh.children;
            walls[0]?.position.set(0, 50, -this.currentRadius);
            walls[1]?.position.set(0, 50, this.currentRadius);
            walls[2]?.position.set(-this.currentRadius, 50, 0);
            walls[3]?.position.set(this.currentRadius, 50, 0);
        }
        if (this.ringMesh) {
            const walls = this.ringMesh.children;
            walls[0]?.position.set(0, 0.08, -this.currentRadius);
            walls[1]?.position.set(0, 0.08, this.currentRadius);
            walls[2]?.position.set(-this.currentRadius, 0.08, 0);
            walls[3]?.position.set(this.currentRadius, 0.08, 0);
        }
    }

    createZone() {
