/**
 * MCP Bridge Extension — Auto-connects MCP servers on session start.
 *
 * Registers tools dynamically from all configured MCP stdio servers.
 * Tools appear as `mcp_{serverName}_{toolName}` in the active tools list.
 *
 * Place in: ~/.pi/agent/extensions/mcp-bridge.ts (auto-discovered)
 */

import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import { Type } from "typebox";

// ─── MCP Server Definitions ────────────────────────────────────────────────

type McpServerDef = {
  name: string;
  command: string;
  args?: string[];
  env?: Record<string, string>;
};

const MCP_SERVERS: McpServerDef[] = [
  {
    name: "codebase-memory",
    command: "C:/Users/maksk/.local/bin/codebase-memory-mcp.exe",
  },
  {
    name: "memory",
    command: "node",
    args: [
      "C:/Users/maksk/AppData/Roaming/npm/node_modules/@modelcontextprotocol/server-memory/dist/index.js",
    ],
  },
  {
    name: "filesystem",
    command: "node",
    args: [
      "C:/Users/maksk/AppData/Roaming/npm/node_modules/@modelcontextprotocol/server-filesystem/dist/index.js",
      "C:/Users/maksk/Desktop/rublox",
    ],
  },
  {
    name: "git",
    command: "node",
    args: [
      "C:/Users/maksk/AppData/Roaming/npm/node_modules/git-mcp/dist/index.js",
    ],
  },
  {
    name: "playwright",
    command: "node",
    args: [
      "C:/Users/maksk/AppData/Roaming/npm/node_modules/@playwright/mcp/cli.js",
    ],
  },
  {
    name: "web-search",
    command: "node",
    args: [
      "C:/Users/maksk/AppData/Roaming/npm/node_modules/@zhafron/mcp-web-search/dist/src/server.js",
    ],
  },
];

// ─── Runtime State ─────────────────────────────────────────────────────────

interface McpClientState {
  client: any; // MCP client instance
  transport: any; // stdio transport
  tools: Array<{ name: string; description: string; inputSchema?: any }>;
}

const mcpStates = new Map<string, McpClientState>();

// ─── Helper: Start an MCP Server ──────────────────────────────────────────

async function startMcpServer(
  name: string,
  def: McpServerDef
): Promise<McpClientState | null> {
  try {
    // Dynamic import with .js extension — jiti resolves these from node_modules
    const clientMod = await import(
      "@modelcontextprotocol/sdk/client/index.js"
    );
    const stdioMod = await import(
      "@modelcontextprotocol/sdk/client/stdio.js"
    );
    // Validate transport is available
    if (!stdioMod.StdioClientTransport && !(stdioMod.default?.StdioClientTransport)) {
      throw new Error(
        `[MCP] ${name}: StdioClientTransport not found in @modelcontextprotocol/sdk/client/stdio.js`
      );
    }
    if (!clientMod.Client && !(clientMod.default?.Client)) {
      throw new Error(
        `[MCP] ${name}: Client not found in @modelcontextprotocol/sdk/client/index.js`
      );
    }

    const { Client } = clientMod.default || clientMod;
    const { StdioClientTransport } = stdioMod.default || stdioMod;

    const transport = new StdioClientTransport({
      command: def.command,
      args: def.args ?? [],
      env: { ...process.env, ...def.env },
    });

    const client = new Client(
      { name: "pi-mcp-bridge", version: "1.0.0" },
      { capabilities: {} }
    );

    await client.connect(transport);

    const toolsResult = await client.listTools();
    const tools = toolsResult.tools ?? [];

    const state: McpClientState = { client, transport, tools };
    mcpStates.set(name, state);

    return state;
  } catch (err) {
    console.error(`[MCP Bridge] Failed to start ${name}: ${err.message}`);
    return null;
  }
}

// ─── Helper: Register Tools for a Server ──────────────────────────────────

function registerMcpTools(serverName: string, tools: Array<any>): void {
  for (const tool of tools) {
    const props: Record<string, any> = {};
    const required: string[] = [];

    const schema = tool.inputSchema ?? { type: "object", properties: {} };
    if (schema.properties) {
      for (const [key, val] of Object.entries(schema.properties)) {
        const v = val as any;
        props[key] = Type.Any(); // Simplified — MCP types are dynamic

        if (
          Array.isArray(schema.required) &&
          schema.required.includes(key)
        ) {
          required.push(key);
        }
      }
    }

    const toolName = `${serverName}_${tool.name}`;

    pi.registerTool({
      name: toolName,
      label: `${serverName}/${tool.name}`,
      description: tool.description ?? `MCP tool from ${serverName}`,
      parameters: Type.Object(props, {
        description: tool.description ?? `Tool ${tool.name}`,
        additionalProperties: false,
      }),
      async execute(_toolCallId, params, _signal, _onUpdate, _ctx) {
        try {
          // Find the right client by matching server name prefix
          let client: any;
          for (const [sn, state] of mcpStates.entries()) {
            if (sn === serverName) {
              client = state.client;
              break;
            }
          }

          if (!client) {
            return {
              content: [
                { type: "text", text: `Error: MCP server "${serverName}" not connected` },
              ],
              details: { isError: true },
            };
          }

          const result = await client.callTool({
            name: tool.name,
            arguments: params,
          });

          const content = result.content ?? [];
          const texts = content
            .map((c: any) => {
              if (c.type === "text") return c.text;
              return JSON.stringify(c);
            })
            .join("\n");

          return {
            content: [{ type: "text", text: texts || "(empty result)" }],
            details: {},
          };
        } catch (err) {
          return {
            content: [
              {
                type: "text",
                text: `Error: ${err.message}`,
              },
            ],
            details: { isError: true },
          };
        }
      },
    });
  }
}

// ─── Extension Factory ────────────────────────────────────────────────────

export default function (pi: ExtensionAPI): void {
  // ── Connect all MCP servers on session start ──────────────────────────

  pi.on(
    "session_start",
    async (_event, ctx) => {
      ctx.ui.setStatus("mcp", "Starting MCP servers...");

      const results: string[] = [];

      for (const def of MCP_SERVERS) {
        ctx.ui.setStatus("mcp", `Starting ${def.name}...`);
        const state = await startMcpServer(def.name, def);
        if (state) {
          registerMcpTools(def.name, state.tools);
          results.push(`${def.name}: OK (${state.tools.length} tools)`);
          ctx.ui.notify(
            `MCP: ${def.name} connected (${state.tools.length} tools)`,
            "info"
          );
        } else {
          results.push(`${def.name}: FAIL`);
        }
      }

      ctx.ui.setStatus("mcp", `MCP: ${results.join(" | ")}`);
      ctx.ui.notify(
        `MCP bridge: ${results.filter((r) => r.includes("OK")).length}/${results.length} servers connected`,
        "info"
      );
    }
  );

  // ── Disconnect all MCP servers on session shutdown ────────────────────

  pi.on(
    "session_shutdown",
    async (_event, _ctx) => {
      for (const [name, state] of mcpStates.entries()) {
        try {
          await state.client.close();
          await state.transport.close();
          console.log(`[MCP Bridge] Closed ${name}`);
        } catch {
          // ignore close errors
        }
      }
      mcpStates.clear();
    }
  );

  // ── Debug command: list connected MCP tools ──────────────────────────

  pi.registerCommand("mcp-list", {
    description: "List all connected MCP tools",
    handler: async (_args, ctx) => {
      const lines: string[] = [];
      for (const [serverName, state] of mcpStates.entries()) {
        for (const tool of state.tools) {
          lines.push(`  ${serverName}/${tool.name}: ${tool.description?.slice(0, 80) ?? ""}`);
        }
      }
      if (lines.length === 0) {
        ctx.ui.notify("No MCP servers connected", "warning");
        return;
      }
      ctx.ui.notify(
        `MCP Tools (${mcpStates.size} servers, ${lines.length} tools):\n${lines.join("\n")}`,
        "info"
      );
    },
  });

  // ── Debug command: reload MCP connection ─────────────────────────────

  pi.registerCommand("mcp-reconnect", {
    description: "Disconnect and reconnect all MCP servers",
    handler: async (_args, ctx) => {
      // Close all existing connections
      for (const [name, state] of mcpStates.entries()) {
        try {
          await state.client.close();
          await state.transport.close();
        } catch {
          // ignore
        }
      }
      mcpStates.clear();
      ctx.ui.notify("MCP servers disconnected, reconnecting...", "info");

      // Reconnect
      for (const def of MCP_SERVERS) {
        const state = await startMcpServer(def.name, def);
        if (state) {
          registerMcpTools(def.name, state.tools);
          ctx.ui.notify(`MCP: ${def.name} reconnected (${state.tools.length} tools)`, "info");
        } else {
          ctx.ui.notify(`MCP: ${def.name} failed to reconnect`, "warning");
        }
      }
    },
  });
}

