    recoverViewState(_reason = 'resume') {
        // CameraController автоматически восстанавливает состояние при разблокировке.
        // Мы просто сбрасываем ввод.
        this.input?.clearInputState?.();
        this.input?.resetLook?.();
    }

    spawnBots() {
        const botCount = this.isMobile()
            ? GAME_CONFIG.bots.mobileCount
            : GAME_CONFIG.bots.desktopCount;
        const spawnPads = this.map.getSpawnPads?.() || [];
        const spawnRadius = GAME_CONFIG.bots.spawnRadius;
        // Player uses pad[0], bots use pads[1..] — each entity gets strictly its own pad
        const botPads = spawnPads.length > 1 ? spawnPads.slice(1) : spawnPads;
        console.log(`[SpawnDebug] Total pads=${spawnPads.length} BotPads=${botPads.length} First=(${spawnPads[0]?.x.toFixed(1)}, ${spawnPads[0]?.z.toFixed(1)}) Second=(${spawnPads[1]?.x.toFixed(1)}, ${spawnPads[1]?.z.toFixed(1)}) Last=(${spawnPads[spawnPads.length-1]?.x.toFixed(1)}, ${spawnPads[spawnPads.length-1]?.z.toFixed(1)})`);

        for (let i = 0; i < botCount; i++) {
            let spawnPos;
            if (botPads.length) {
                // Each bot gets its own pad, no cycling, no offsets
                const pad = botPads[i];
                if (!pad) break;

                // Bots spawn ON the pad surface (pad.y = platform surface y=2)
                const botHeight = 1.7;
                spawnPos = new THREE.Vector3(pad.x, pad.y + botHeight, pad.z);
                if (i < 3) console.log(`[SpawnDebug] Bot ${i}: pad=(${pad.x.toFixed(2)}, ${pad.z.toFixed(2)}) spawn=(${spawnPos.x.toFixed(2)}, ${spawnPos.z.toFixed(2)}) distFromCenter=${Math.sqrt(pad.x*pad.x + pad.z*pad.z).toFixed(2)}`);
            } else {
                const angle = (i / botCount) * Math.PI * 2;
                spawnPos = new THREE.Vector3(
                    Math.cos(angle) * spawnRadius,
                    2 + 1.9,
                    Math.sin(angle) * spawnRadius
                );
            }

            const bot = new Bot(this.scene, i, spawnPos);
            bot.mapRef = this.map;
            bot.physics.onGround = true;
            bot.isFrozen = true;
            bot.state = 'spawn';
            bot.target = null;
            bot.patrolTarget = null;
            // Start pre-loot phase early — bots can loot during countdown
            bot.noCombatUntil = performance.now() + this.botLootPhaseDuration * 1000;
            bot.pickupLoot?.({ type: 'weapon', weaponType: 'knife' });
            this.physics.addEntity(bot);
            this.entityManager.addEntity(bot);
            this.bots.push(bot);
        }
        this.setupBotLodBatch();
    }

    setupBotLodBatch() {
        this.botLodBatch?.parent?.remove(this.botLodBatch);
        if (!this.bots.length) return;
        const group = new THREE.Group();
        const parts = [
            ['shirt', new THREE.BoxGeometry(0.9, 1, 0.5), 1.05],
            ['skin', new THREE.BoxGeometry(0.65, 0.65, 0.65), 1.9],
            ['pants', new THREE.BoxGeometry(0.72, 0.8, 0.34), 0.4],
            ['hair', new THREE.BoxGeometry(0.69, 0.22, 0.69), 2.24]
        ];
        this.botLodBatches = [];
        this.botLodBatchesByVariant = Array.from({ length: this.bots[0].variants.length }, () => []);
        for (let variant = 0; variant < this.bots[0].variants.length; variant++) {
            const outfit = this.bots[0].variants[variant];
            for (const [colorKey, geometry, y] of parts) {
                const material = new THREE.MeshBasicMaterial({ color: outfit[colorKey] || 0x5588aa, fog: false, toneMapped: false });
                const batch = new THREE.InstancedMesh(geometry, material, this.bots.length);
                batch.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
                batch.frustumCulled = false;
                batch.count = 0;
                batch.userData.entityLodBatch = true;
                batch.userData.variant = variant;
                batch.userData.localMatrix = new THREE.Matrix4().makeTranslation(0, y, 0);
                this.botLodBatches.push(batch);
                this.botLodBatchesByVariant[variant].push(batch);
                group.add(batch);
            }
        }
        for (const bot of this.bots) {
            bot.mesh.userData.useBatchedLod = true;
            if (bot.mesh.userData.lodProxy) bot.mesh.userData.lodProxy.visible = false;
        }
        this.scene.add(group);
        this.botLodBatch = group;
        this._botLodMatrix = new THREE.Matrix4();
        this._botLodCounts = new Uint16Array(this.botLodBatchesByVariant.length);
    }

